// 이 함수는 그대로 두세요
async function count(url) {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error('불러오지 못했습니다 (' + res.status + ')');
  }
  const list = await res.json();
  return list.length;
}

async function countAll(urls) {
  try {
    const counts = await Promise.all(urls.map((url) => count(url)));
    const total = counts.reduce((sum, n) => sum + n, 0);
    return { total, counts };
  } catch (e) {
    return { error: e.message };
  }
}
